test('a signed booking is taken in', () => {
  const app = start(env);
  const body = '{"room":"A-3","date":"2026-12-01"}';
  assert.deepEqual(app.receive(body, sign(body, 'k-2041')), { status: 202, booking: { room: 'A-3', date: '2026-12-01' } });
